		t.Fatalf("getSessionsBranchTree() error = %v", err)
	}

	fakeID := id.MustCheckpointID("ffffffffffff")
	_, err = CollectTranscriptBlobHashes(tree, fakeID)
	if err == nil {
		t.Error("expected error for nonexistent checkpoint")
	}
}

