	trackingRef := cpkg.MetadataTrackingRef(ctx)
	refDisplay := strings.TrimPrefix(string(localRef), "refs/heads/")

	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

