365		// Reconcile disconnected metadata branches before rebasing.
366		// The fetch above updated the remote-tracking ref, so reconciliation
367		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
368		// this cherry-picks local commits onto remote tip, updating the local ref.
369		// If reconciliation fails, abort — proceeding to rebase on disconnected
370		// branches would silently combine unrelated histories.
371		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
372			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
373		}
374	
375		// Get local branch (re-read after potential reconciliation update)
376		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
377		if err != nil {
378			return fmt.Errorf("failed to get local ref: %w", err)
379		}
380	
381		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
382		remoteRef, err := repo.Reference(fetchedRefName, true)
383		if err != nil {
384			return fmt.Errorf("failed to get remote ref: %w", err)
385		}
386	
387		// If local is already at or behind remote, fast-forward
388		if localRef.Hash() == remoteRef.Hash() {
389			return nil
390		}
391	
392		// Find merge base
393		repoPath, err := getRepoPath(repo)
394		if err != nil {
395			return fmt.Errorf("failed to get repo path: %w", err)
396		}
397		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
398		if err != nil {
399			return fmt.Errorf("failed to find merge base: %w", err)
400		}
401	
402		// If local is ancestor of remote (merge base == local), fast-forward to remote
403		if mergeBase == localRef.Hash() {
404			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
405			if err := repo.Storer.SetReference(ref); err != nil {
406				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
407			}
408			if usedTempRef {
409				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
