		strategyOptions = make(map[string]any)
	}
	if _, exists := strategyOptions["filtered_fetches"]; !exists {
		strategyOptions["filtered_fetches"] = true
	}
	if len(strategyOptions) > 0 {
		settings["strategy_options"] = strategyOptions
